 static string Sha(string path){using(var s=SHA256.Create())using(var f=File.OpenRead(path))return BitConverter.ToString(s.ComputeHash(f)).Replace("-","").ToLowerInvariant();}
 static byte[] Redirect(long entry,long cave,int size){byte[] b=new byte[size];for(int i=0;i<size;i++)b[i]=0x90;b[0]=0xe9;Buffer.BlockCopy(BitConverter.GetBytes(checked((int)(cave-entry-5))),0,b,1,4);return b;}
 static void ProtectedWrite(IntPtr h,long entry,byte[] value,ref uint originalProtection){uint old;Check(VirtualProtectEx(h,new IntPtr(entry),new IntPtr(value.Length),RWX,out old),"Protect redirect");if(originalProtection==0)originalProtection=old;try{Write(h,entry,value);Check(FlushInstructionCache(h,new IntPtr(entry),new IntPtr(value.Length)),"Flush redirect");Check(Equal(Read(h,entry,value.Length),value),"Verify redirect");}finally{uint ignored;Check(VirtualProtectEx(h,new IntPtr(entry),new IntPtr(value.Length),originalProtection,out ignored),"Restore redirect protection");}}
 static IntPtr Allocate(IntPtr h,long image){for(long d=0x20000000;d<=0x60000000;d+=0x10000){var a=VirtualAllocEx(h,new IntPtr(image+d),new IntPtr(0x9000),0x3000,RW);if(a!=IntPtr.Zero)return a;}return IntPtr.Zero;}
 static Process Supported(int pid){var p=Process.GetProcessById(pid);if(!String.Equals(p.ProcessName,"Zoe2Mars",StringComparison.OrdinalIgnoreCase)||Sha(p.MainModule.FileName)!=ExpectedExe)throw new Exception("Unsupported game process/executable");return p;}
 static void Attach(int pid){
  var process=Supported(pid);long image=process.MainModule.BaseAddress.ToInt64();IntPtr h=OpenProcess(0x438,false,pid);Check(h!=IntPtr.Zero,"Open game process");
  IntPtr allocation=IntPtr.Zero;bool committed=false,uncertain=false;var attempted=new List<Hook>();
  try{
   foreach(var hook in Hooks)if(!Equal(Read(h,image+hook.Entry-ImageBase,hook.Stolen.Length),hook.Stolen))throw new Exception("Native Viper bytes differ or a conflicting helper is active at "+hook.Entry.ToString("x"));
   allocation=Allocate(h,image);Check(allocation!=IntPtr.Zero,"Allocate Viper code/configuration");long cave=allocation.ToInt64();byte[] code=BuildCave(image,cave),config=Config(image);
   Write(h,cave,code);Write(h,cave+0x8000,config);Check(Equal(Read(h,cave,code.Length),code)&&Equal(Read(h,cave+0x8000,config.Length),config),"Verify Viper payload");
   uint old;Check(VirtualProtectEx(h,allocation,new IntPtr(0x8000),RX,out old),"Protect Viper code");Check(FlushInstructionCache(h,allocation,new IntPtr(code.Length)),"Flush Viper code");
   foreach(var hook in Hooks){attempted.Add(hook);ProtectedWrite(h,image+hook.Entry-ImageBase,Redirect(image+hook.Entry-ImageBase,cave+hook.Cave,hook.Stolen.Length),ref hook.Protection);}
   committed=true;Console.WriteLine("Vic Viper movement, arena reachability and native clone-death guards active. Original Mars behaviour retained. Disk executable unchanged.");
  }catch(Exception failure){
   for(int i=attempted.Count-1;i>=0;i--){var hook=attempted[i];try{ProtectedWrite(h,image+hook.Entry-ImageBase,hook.Stolen,ref hook.Protection);}catch{uncertain=true;}}
   if(uncertain)throw new Exception("Viper attachment failed and rollback could not be verified. Close the game. "+failure.Message);
   throw;
  }finally{if(allocation!=IntPtr.Zero&&!committed&&!uncertain)VirtualFreeEx(h,allocation,IntPtr.Zero,0x8000);CloseHandle(h);}
 }
 static void Capture(int pid,string output){
  var process=Supported(pid);long image=process.MainModule.BaseAddress.ToInt64();IntPtr h=OpenProcess(0x410,false,pid);Check(h!=IntPtr.Zero,"Open read-only Viper status");
  try{byte[] redirect=Read(h,image+0x772d10,5);if(redirect[0]!=0xe9)throw new Exception("Viper combat helper is not attached");long cave=image+0x772d10+5+BitConverter.ToInt32(redirect,1);byte[] code=BuildCave(image,cave);if(!Equal(Read(h,cave,code.Length),code))throw new Exception("A different Viper helper occupies the update entry");byte[] c=Read(h,cave+0x8000,3656);if(BitConverter.ToUInt32(c,44)!=0x56495032)throw new Exception("Viper configuration marker differs");var actors=new List<object>();for(int i=0;i<128;i++){int at=72+i*24;long actor=BitConverter.ToInt64(c,at);if(actor==0)continue;actors.Add(new {pointer=actor.ToString("x"),serial=BitConverter.ToUInt32(c,at+8),native_death_seen=BitConverter.ToUInt32(c,at+12)!=0,native_completion_seen=BitConverter.ToUInt32(c,at+16)!=0});}string stage=System.Text.Encoding.ASCII.GetString(Read(h,image+0x1535830,8)).Split((char)0)[0];string seed="unknown";string manifest=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"..","manifest.json");if(File.Exists(manifest)){var m=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(File.ReadAllText(manifest));if(m.ContainsKey("seed"))seed=Convert.ToString(m["seed"]);}var report=new {format=1,seed=seed,arena=stage,helper="ViperCombatAdapter",read_only=true,spawns=BitConverter.ToUInt32(c,48),repositions=BitConverter.ToUInt32(c,52),flight_redirects=BitConverter.ToUInt32(c,56),native_completions_observed=BitConverter.ToUInt32(c,60),actors=actors};File.WriteAllText(output,new JavaScriptSerializer().Serialize(report));Console.WriteLine("Read-only Viper status captured: "+output);
  }finally{CloseHandle(h);}
 }
 static void SelfTest(string folder){Directory.CreateDirectory(folder);foreach(long image in new long[]{ImageBase,0x180000000,0x7ff600000000})foreach(long offset in new long[]{0x20000000,0x20010000,0x60000000}){long cave=image+offset;byte[] b=BuildCave(image,cave),c=Config(image);if(c.Length!=3656||b.Length>=0x8000)throw new Exception("Viper payload bounds");File.WriteAllBytes(Path.Combine(folder,"viper-"+image.ToString("x")+"-"+offset.ToString("x")+".bin"),b);File.WriteAllBytes(Path.Combine(folder,"config-"+image.ToString("x")+".bin"),c);}Console.WriteLine("Viper payload fixtures at three bases and three cave offsets; no game opened.");}
 public static int Main(string[] args){try{if(args.Length==2&&args[0]=="--self-test"){SelfTest(args[1]);return 0;}if(args.Length==2&&args[0]=="--attach-menu"){Attach(Int32.Parse(args[1]));return 0;}if(args.Length==3&&args[0]=="--capture-status"){Capture(Int32.Parse(args[1]),args[2]);return 0;}Console.WriteLine("--self-test folder; --attach-menu PID; --capture-status PID output.json");return 0;}catch(Exception ex){Console.Error.WriteLine(ex.Message);return 1;}}
}
